{"path":"assets/css/styles.css","content":"/*
  Dental Premium Template Styles
  System font stack only. No external assets.
*/
:root{
  --brand-1:#0e7c86; /* deep teal */
  --brand-2:#0ab3c9; /* aqua */
  --accent:#ffd166; /* warm accent */
  --bg:#f3fbfd;
  --surface:#ffffff;
  --text:#0f2a2e;
  --muted:#5b777b;
  --ok:#1f9254;
  --warn:#a45700;
  --err:#a3122b;
  --radius:14px;
  --radius-sm:10px;
  --shadow-sm:0 2px 6px rgba(6,34,39,.06);
  --shadow-md:0 8px 24px rgba(6,34,39,.10);
  --shadow-lg:0 18px 60px rgba(6,34,39,.18);
  --container:1160px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
html:focus-within{scroll-behavior:smooth}
body{
  margin:0;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,Apple Color Emoji,Segoe UI Emoji,Segoe UI Symbol,sans-serif;
  color:var(--text);
  background:linear-gradient(180deg,var(--bg),#ffffff 40%);
  line-height:1.6;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}
img,svg{max-width:100%;display:block}
.container{max-width:var(--container);margin-inline:auto;padding-inline:1rem}
.grid{display:grid;gap:1rem}
.grid-2{grid-template-columns:1fr;gap:1.5rem}
.grid-3{grid-template-columns:1fr;gap:1.5rem}
@media(min-width:768px){.grid-2{grid-template-columns:1fr 1fr}.grid-3{grid-template-columns:repeat(3,1fr)}}
@media(min-width:1024px){.grid-3-lg{grid-template-columns:2fr 1fr 1fr}}
.stack>*+*{margin-top:var(--stack,1rem)}
.section{padding:3rem 0}
.section--tight{padding:2rem 0}
.section--hero{padding:5rem 0 3rem}
.card{background:var(--surface);border-radius:var(--radius);box-shadow:var(--shadow-sm);border:1px solid rgba(14,124,134,.08)}
.card--hover:hover{box-shadow:var(--shadow-md);transform:translateY(-2px);transition:all .25s ease}
.badge{display:inline-flex;align-items:center;gap:.5rem;padding:.35rem .6rem;border-radius:999px;background:rgba(10,179,201,.12);color:var(--brand-1);font-weight:600;font-size:.85rem}
.kicker{font-size:.9rem;color:var(--brand-1);letter-spacing:.04em;text-transform:uppercase;font-weight:700}
.h1{font-size:clamp(2rem,3vw+1rem,3rem);line-height:1.15;margin:0 0 1rem}
.h2{font-size:clamp(1.5rem,2vw+1rem,2.2rem);margin:0 0 .75rem}
.h3{font-size:1.25rem;margin:0 0 .5rem}
.lead{font-size:1.1rem;color:var(--muted);max-width:60ch}
.text-muted{color:var(--muted)}
hr{border:none;border-top:1px solid rgba(14,124,134,.12);margin:1.25rem 0}
.button,.btn{--bg:var(--brand-1);--fg:#fff;display:inline-flex;align-items:center;justify-content:center;gap:.5rem;padding:.9rem 1rem;border-radius:12px;background:var(--bg);color:var(--fg);text-decoration:none;font-weight:700;box-shadow:var(--shadow-sm);border:1px solid rgba(0,0,0,.04);cursor:pointer}
.btn--primary{--bg:linear-gradient(180deg,var(--brand-2),var(--brand-1))}
.btn--ghost{--bg:transparent;--fg:var(--brand-1);border:1.5px solid rgba(14,124,134,.35);box-shadow:none}
.btn--accent{--bg:var(--accent);--fg:#17323a;color:#17323a}
.btn:focus-visible{outline:3px solid #91e3ee;outline-offset:2px}
.link{color:var(--brand-1);text-decoration:none;border-bottom:1px dashed rgba(14,124,134,.35)}
.link:hover{border-bottom-color:transparent}

/* Header */
.topbar{background:linear-gradient(90deg,rgba(10,179,201,.12),rgba(14,124,134,.12));border-bottom:1px solid rgba(14,124,134,.12)}
.topbar-inner{display:flex;align-items:center;justify-content:space-between;gap:.5rem;padding:.4rem 0;font-size:.95rem}
.topbar a{color:var(--brand-1);text-decoration:none}
.header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.8);backdrop-filter:saturate(180%) blur(8px);border-bottom:1px solid rgba(14,124,134,.08)}
.nav{display:flex;align-items:center;justify-content:space-between;padding:.8rem 0}
.logo{display:flex;align-items:center;gap:.7rem;font-weight:800;color:var(--text);text-decoration:none}
.logo .mark{inline-size:38px;block-size:38px;border-radius:10px;background:radial-gradient(circle at 30% 30%,#9bf0ff,transparent 40%),linear-gradient(160deg,var(--brand-2),var(--brand-1));box-shadow:inset 0 0 0 1px rgba(255,255,255,.5),var(--shadow-sm)}
.nav-links{display:none;gap:1rem;align-items:center}
.nav-links a{color:var(--text);text-decoration:none;font-weight:600;padding:.5rem .6rem;border-radius:10px}
.nav-links a[aria-current="page"],.nav-links a:hover{background:rgba(10,179,201,.12)}
.menu-toggle{display:inline-flex;align-items:center;justify-content:center;width:44px;height:44px;border-radius:10px;border:1px solid rgba(14,124,134,.25);background:#fff}
@media(min-width:900px){.menu-toggle{display:none}.nav-links{display:flex}}
.mobile-panel{display:none;position:fixed;inset:0 0 auto 0;top:64px;background:#fff;border-top:1px solid rgba(14,124,134,.12);box-shadow:var(--shadow-md);padding:1rem}
.mobile-panel.open{display:block}
.mobile-panel a{display:block;padding:.8rem;border-radius:10px;color:var(--text);text-decoration:none}
.mobile-panel a:hover{background:rgba(10,179,201,.08)}

/* Hero */
.hero{position:relative;overflow:hidden;border-radius:calc(var(--radius) + 6px);background:linear-gradient(180deg,rgba(10,179,201,.15),rgba(14,124,134,.15)),#ffffff}
.hero::after{content:"";position:absolute;inset:auto -10% -40% -10%;height:320px;background:url('../img/hero-abstract.svg') center/cover no-repeat;opacity:.4;filter:saturate(110%)}
.hero-inner{display:grid;gap:2rem;grid-template-columns:1fr}
.hero-media{order:-1}
.hero .trust{display:flex;gap:1rem;flex-wrap:wrap;margin-top:1rem}
@media(min-width:900px){.hero-inner{grid-template-columns:1.1fr .9fr;align-items:center}.hero-media{order:unset}}

/* Feature rows */
.icon-row{display:grid;grid-template-columns:1fr;gap:1rem}
.icon{width:42px;height:42px;border-radius:12px;display:inline-grid;place-items:center;background:linear-gradient(180deg,var(--brand-2),var(--brand-1));color:#fff;box-shadow:var(--shadow-sm)}
@media(min-width:720px){.icon-row{grid-template-columns:repeat(3,1fr)}}

/* Forms */
.form{display:grid;gap:1rem}
.input{display:grid;gap:.4rem}
.input label{font-weight:700}
.input input,.input select,.input textarea{padding:.85rem 1rem;border-radius:12px;border:1.5px solid rgba(14,124,134,.25);background:#fff;color:var(--text)}
.input input:focus,.input select:focus,.input textarea:focus{outline:3px solid #b5f1f6;border-color:transparent}
.input .help{font-size:.9rem;color:var(--muted)}
.form .inline{display:flex;gap:1rem;flex-wrap:wrap}
.callout{padding:1rem;border-radius:12px;background:rgba(31,146,84,.08);border:1px solid rgba(31,146,84,.25)}
.callout--warn{background:rgba(255,209,102,.2);border-color:rgba(255,209,102,.7)}
.callout--muted{background:rgba(10,179,201,.08);border-color:rgba(10,179,201,.25)}

/* Lists & accordions */
.list-clean{list-style:none;margin:0;padding:0}
.benefit{display:flex;gap:.75rem}
.benefit .dot{width:12px;height:12px;border-radius:999px;background:linear-gradient(180deg,var(--brand-2),var(--brand-1));margin-top:.5rem;flex:0 0 12px}
.accordion{border-radius:12px;border:1px solid rgba(14,124,134,.15);overflow:hidden}
.accordion details{border-top:1px solid rgba(14,124,134,.12)}
.accordion summary{cursor:pointer;list-style:none;padding:1rem 1.1rem;font-weight:700;display:flex;justify-content:space-between;align-items:center}
.accordion summary::-webkit-details-marker{display:none}
.accordion .panel{padding:0 1.1rem 1rem}

/* Footer */
.footer{background:#062f34;color:#e9fbfe}
.footer a{color:#c9f5fb;text-decoration:none}
.footer .footer-grid{display:grid;gap:2rem;grid-template-columns:1fr}
.footer .brand{display:flex;align-items:center;gap:.8rem}
.footer .brand .mark{inline-size:32px;block-size:32px;border-radius:9px;background:linear-gradient(160deg,var(--brand-2),var(--brand-1))}
@media(min-width:800px){.footer .footer-grid{grid-template-columns:2fr 1fr 1fr 1.4fr}}
.subfooter{border-top:1px solid rgba(255,255,255,.12);font-size:.95rem;padding:1rem 0;color:#bfeef5}

/* Utilities */
.center{text-align:center}
.max-60{max-width:60ch}
.mt-0{margin-top:0}.mt-1{margin-top:.5rem}.mt-2{margin-top:1rem}.mt-3{margin-top:1.5rem}.mt-4{margin-top:2rem}
.mb-0{margin-bottom:0}.mb-1{margin-bottom:.5rem}.mb-2{margin-bottom:1rem}.mb-3{margin-bottom:1.5rem}.mb-4{margin-bottom:2rem}
.flex{display:flex;gap:1rem}
.flex-wrap{flex-wrap:wrap}
.items-center{align-items:center}
.justify-between{justify-content:space-between}
.round{border-radius:999px}
.sr-only{position:absolute !important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.divider{height:1px;background:rgba(14,124,134,.12);margin:1.25rem 0}
.pill{display:inline-block;padding:.25rem .6rem;border:1px solid rgba(14,124,134,.25);border-radius:999px;color:var(--muted);font-weight:600;font-size:.85rem}

/* Map placeholder */
.map{height:280px;border-radius:14px;background:repeating-linear-gradient(45deg,rgba(10,179,201,.08),rgba(10,179,201,.08) 10px,rgba(14,124,134,.08) 10px,rgba(14,124,134,.08) 20px)}

/* Review stars */
.stars{--c:#ffc84c;display:inline-flex;gap:.15rem}
.star{width:18px;height:18px;display:inline-block;background:conic-gradient(var(--c) 0 72deg,transparent 72deg) top/100% 50% no-repeat,conic-gradient(var(--c) 0 72deg,transparent 72deg) bottom/100% 50% no-repeat;clip-path:polygon(50% 0,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%)}

/* Tables */
.table{width:100%;border-collapse:collapse}
.table th,.table td{padding:.75rem;border-bottom:1px solid rgba(14,124,134,.12);text-align:left}
.table th{background:rgba(10,179,201,.08)}

/* Print */
@media print{
  .topbar,.header,.mobile-panel,.btn,.button{display:none !important}
  .section{padding:1rem 0}
  .card, .hero{box-shadow:none;border:1px solid #ddd}
}

/* Motion */
@media (prefers-reduced-motion: reduce){
  *{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important;scroll-behavior:auto !important}
}
"}
{"path":"assets/js/main.js","content":"(function(){
  'use strict';
  const $ = (s, c=document)=>c.querySelector(s);
  const $$ = (s, c=document)=>Array.from(c.querySelectorAll(s));

  // Mobile nav toggle
  const toggle = $('.menu-toggle');
  const panel = $('.mobile-panel');
  if(toggle){
    toggle.addEventListener('click',()=>{
      const open = panel.classList.toggle('open');
      toggle.setAttribute('aria-expanded', String(open));
      if(open){ panel.querySelector('a')?.focus(); }
    });
  }

  // Close mobile panel on link click
  $$('.mobile-panel a').forEach(a=>a.addEventListener('click',()=>{
    panel.classList.remove('open');
    toggle?.setAttribute('aria-expanded','false');
  }));

  // Accessible accordions (for any <details>)
  $$('details').forEach(d => {
    const s = d.querySelector('summary');
    if(s){ s.setAttribute('role','button'); s.setAttribute('aria-expanded', d.open ? 'true' : 'false'); }
    d.addEventListener('toggle',()=>{
      s?.setAttribute('aria-expanded', d.open ? 'true' : 'false');
    });
  });

  // Simple form handlers (demo only)
  function serialize(form){
    const data = new FormData(form);
    return Object.fromEntries(data.entries());
  }

  function announce(msg,type='status'){
    const region = $('#aria-live') || (function(){
      const live = document.createElement('div');
      live.id = 'aria-live';
      live.className = 'sr-only';
      live.setAttribute('aria-live','polite');
      document.body.appendChild(live);
      return live;
    })();
    region.textContent = msg;
    if(type==='error') console.error(msg); else console.info(msg);
  }

  function mockSubmit(form){
    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const btn = form.querySelector('[type="submit"]');
      const orig = btn?.textContent;
      btn && (btn.disabled = true, btn.textContent = 'Submitting…');
      const payload = serialize(form);
      try{ localStorage.setItem('form:'+ (form.id||form.name||'generic'), JSON.stringify(payload)); }catch(e){}
      setTimeout(()=>{
        btn && (btn.disabled = false, btn.textContent = orig||'Submit');
        const msg = 'Thanks! Your information has been saved locally. Please connect this form to your backend to receive submissions.';
        announce(msg);
        const conf = form.querySelector('.form-confirm');
        if(conf){ conf.hidden = false; conf.focus?.(); }
      }, 600);
    });
  }

  $$('.form[data-mock-submit]')?.forEach(mockSubmit);

  // Client-side date minimum (today)
  $$('input[type="date"]').forEach(inp=>{
    const t = new Date();
    const pad = n=>String(n).padStart(2,'0');
    const val = `${t.getFullYear()}-${pad(t.getMonth()+1)}-${pad(t.getDate())}`;
    if(!inp.min) inp.min = val;
  });

  // Auto-fill phone tel: links with accessible labels
  $$('a[href^="tel:"]').forEach(a=>{
    if(!a.getAttribute('aria-label')){
      a.setAttribute('aria-label','Call our office');
    }
  });
})();
"}
