{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#0e7c86">
  <title>Home | {{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} in {{CITY}}, {{STATE}} delivers premium family, cosmetic, and implant dentistry with gentle, state-of-the-art care. {{TAGLINE}}">
  <link rel="canonical" href="/">
  <meta property="og:type" content="website">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Premium family, cosmetic, and implant dentistry in {{CITY}}, {{STATE}}. Call {{PHONE}}.">
  <meta property="og:url" content="/">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta name="twitter:description" content="Gentle, modern dental care in {{CITY}}, {{STATE}}. Call {{PHONE}}.">
  <meta name="twitter:image" content="assets/img/hero-abstract.svg">
  <link rel="icon" href="assets/img/hero-abstract.svg" type="image/svg+xml">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">{
    "@context":"https://schema.org",
