        <h1 class="h1">Book an appointment</h1>
        <p class="text-muted">Choose a preferred date and time. We’ll confirm shortly by phone or email.</p>
        <form id="booking-form" class="form" data-mock-submit>
          <div class="inline">
            <div class="input" style="flex:1 1 220px"><label for="name">Full name</label><input id="name" name="name" type="text" autocomplete="name" required></div>
            <div class="input" style="flex:1 1 220px"><label for="phone">Phone</label><input id="phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" required></div>
          </div>
          <div class="inline">
            <div class="input" style="flex:1 1 220px"><label for="email">Email</label><input id="email" name="email" type="email" autocomplete="email"></div>
            <div class="input" style="flex:1 1 220px"><label for="reason">Reason</label><select id="reason" name="reason"><option>Exam & cleaning</option><option>Tooth pain / emergency</option><option>Consultation</option><option>Whitening</option><option>Other</option></select></div>
          </div>
          <div class="inline">
            <div class="input" style="flex:1 1 200px"><label for="date">Preferred date</label><input id="date" name="date" type="date" required></div>
            <div class="input" style="flex:1 1 200px"><label for="time">Preferred time</label><select id="time" name="time"><option>Morning</option><option>Midday</option><option>Afternoon</option></select></div>
          </div>
          <div class="input"><label for="notes">Notes</label><textarea id="notes" name="notes" rows="4" placeholder="Anything we should know before your visit?"></textarea><p class="help">Please don’t include sensitive health information.</p></div>
          <div class="input"><label><input type="checkbox" name="consent" required> I agree to be contacted by phone or email to confirm my appointment.</label></div>
          <button type="submit" class="btn btn--primary">Request appointment</button>
          <p class="form-confirm callout mt-2" tabindex="-1" hidden>Your request was saved locally. Connect this form to your backend to receive submissions.</p>
        </form>
      </section>

      <aside class="card" style="padding:1.5rem">
        <h2 class="h2">Or book by phone</h2>
        <p class="text-muted">Prefer to talk? We’ll find a time that works.</p>
        <a class="btn btn--accent" href="tel:{{PHONE}}">Call {{PHONE}}</a>
        <hr>
        <h3 class="h3">Location & hours</h3>
        <p class="text-muted">{{ADDRESS}}<br>{{CITY}}, {{STATE}} {{ZIP}}</p>
        <p><strong>Hours:</strong> {{HOURS}}</p>
        <div class="map" aria-label="Map placeholder for our office"></div>
      </aside>
    </div>
